rations , headers = { Authorization : f Bearer { os.environ[ RECRAFT_API_TOKEN ] } }, json = { prompt : a red fox in a snowy forest, flat vector , model : recraftv4_1_vector }, ) if not response.ok: raise SystemExit ( f { response.status_code } : { response.text } ) print (response.json()[ data ][ 0 ][ url ]) # pip install openai import os from openai import OpenAI client = OpenAI( base_url = https://external.api.recraft.ai/v1 , api_key = os.environ[ RECRAFT_API_TOKEN ], ) response = client.images.generate( prompt = a red fox in a snowy forest, flat vector , model = recraftv4_1_vector , ) print (response.data[ 0 ].url) const response = await fetch ( https://external.api.recraft.ai/v1/images/generations , { method: POST , headers: { Authorization: `Bearer ${ process . env . RECRAFT_API_TOKEN } ` , Content-Type : application/json , }, body: JSON . stringify ({ prompt: a red fox in a snowy forest, flat vector , model: recraftv4_1_vector }), }); if ( ! response . ok ) throw new Error ( await response . text ()); console . log (( await response . json ()). data [ 0 ]. url ); You get a link to an SVG file, valid for about 24 hours: { created : 1759140000 , credits : 80 , data : [{ image_id : 0e6a1b8c-5b1f-4a8e-9f3a-2c7d4e8b9a10 , url : https://... }] } New to the API? The Quickstart walks through each step. ​ Models V4.1 Flash About 1.3 s and $0.007 per image, quality close to V4.1. Raster Fastest V4.1 The default. Photorealism, illustration, and strong short prompts. From $0.035. Raster Vector Styles V4 Styles Match any style from 1 to 10 reference images. From $0.035. Raster Vector Style match V4 Design taste and production-grade vectors. From $0.04. Raster Vector Styles V3 Curated styles, exact text placement, and all editing operations. From $0.04. Inpaint Outpaint Text layout V2 The cheapest vector option, for icons and simple illustration. From $0.022. Raster Vector Icons Not sure which to pick? Compare them in All models . ​ What else you can do Edit Image to image, inpaint, outpaint, and erase region. Background Remove, replace, or generate a background. Vectorize Turn a PNG or JPG into SVG for $0.01. Upscale Crisp or creative upscale, and enhance details. Styles Save your brand look once, reuse it in every request. Enhance prompt Expand a short prompt into a detailed one. ​ Reference Endpoints : every operation with its parameters. Pricing and Limits and sizes : prices, sizes, prompt limits, and rate limits. Clients and SDKs : plain HTTP or the OpenAI Python library. Use with AI tools : llms.txt , Markdown pages, and the Claude Code skill. Quickstart instagram github linkedin Powered by This documentation is built and hosted on Mintlify, a developer documentation platform {"docsConfig":{"theme":"mint","$schema":"https://mintlify.com/docs.json","name":"Recraft","colors":{"primary":"#6a3eff","light":"#9175ff","dark":"#6a3eff"},"logo":{"light":"https://mintcdn.com/recraft/fZI97QJ1Olgx-I7K/logo/recraft-docs-light.svg?fit=max&auto=format&n=fZI97QJ1Olgx-I7K&q=85&s=7bf43c710378a83bc311d3613660ba4b","dark":"https://mintcdn.com/recraft/fZI97QJ1Olgx-I7K/logo/recraft-docs-dark.svg?fit=max&auto=format&n=fZI97QJ1Olgx-I7K&q=85&s=baa5f6cf6902e24118c55891c40f3c7a"},"favicon":{"light":"https://mintcdn.com/recraft/XhNLS_RBRXuDJbD8/images/faviconiconwhite.svg?fit=max&auto=format&n=XhNLS_RBRXuDJbD8&q=85&s=1c43f8ca28983c27e4c122bfd76dba25","dark":"https://mintcdn.com/recraft/XhNLS_RBRXuDJbD8/images/faviconiconwhite.svg?fit=max&auto=format&n=XhNLS_RBRXuDJbD8&q=85&s=1c43f8ca28983c27e4c122bfd76dba25"},"api":{"openapi":"api-reference/openapi.json"},"appearance":{"default":"system","strict":false},"background":{"color":{"light":"#ffffff","dark":"#070707"}},"navbar":{"primary":{"type":"button","label":"Sign in","href":"https://www.recraft.ai/auth/login"}},"footer":{"socials":{"instagram":"https://www.instagram.com/recraftai","github":"https://github.com/recraft-ai/ComfyUI-RecraftAI","linkedin":"https://www.linkedin.com/company/recraftai"}},"fonts":{"